/**
 * Deterministic particle soak test.
 *
 * - Positions/velocities are Q16.16 fixed-point numbers stored as bigint
 *   (1.0 == 65536n). All arithmetic is exact integer math, so the simulation
 *   is fully deterministic and free of floating-point drift.
 * - Initial velocities come from a seeded xorshift32 PRNG.
 * - 200 particles bounce inside a 1000x1000 box for exactly 10000 ticks.
 * - A 32-bit FNV-1a hash is computed over every particle's state.
 */

export const SCALE = 65536n; // Q16.16
const BOX = 1000;
const MAX_POS = BigInt(BOX) * SCALE; // exclusive upper bound

const NUM_PARTICLES = 200;
const TICKS = 10000;

/** xorshift32: returns next raw uint32 and mutates state. */
function xorshift32(state: { s: number }): number {
  let x = state.s | 0;
  x ^= x << 13;
  x ^= x >>> 17;
  x ^= x << 5;
  state.s = x | 0;
  return x >>> 0;
}

interface Particle {
  // Q16.16 fixed point, stored exactly (always non-negative position)
  px: bigint;
  py: bigint;
  vx: bigint; // may be negative
  vy: bigint;
}

/** Serialize a signed bigint to two's-complement little-endian bytes (64-bit). */
function toBytes(v: bigint): number[] {
  const masked = BigInt.asUintN(64, v);
  const out: number[] = [];
  for (let i = 0n; i < 8n; i++) {
    out.push(Number((masked >> (i * 8n)) & 0xffn));
  }
  return out;
}

/** 32-bit FNV-1a over a byte stream. */
function fnv1a(bytes: number[]): string {
  let h = 0x811c9dc5;
  for (const b of bytes) {
    h ^= b;
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, "0");
}

/** Run the full soak test and return the FNV-1a hash of all particle states. */
export function runSim(seed: number): string {
  if (!Number.isInteger(seed)) throw new Error("seed must be an integer");

  const rng = { s: seed | 0 };

  // Initialize particles on integer grid positions with RNG-driven velocities.
  const particles: Particle[] = [];
  for (let i = 0; i < NUM_PARTICLES; i++) {
    // Non-trivial deterministic starting spread inside the box.
    const px = BigInt((i * 37 + 13) % BOX) * SCALE;
    const py = BigInt((i * 53 + 7) % BOX) * SCALE;
    // Velocities in roughly [-2.0, +2.0] fixed-point units per tick.
    const vx =
      (BigInt(xorshift32(rng) % 65536) - 32768n) * 4n + BigInt(xorshift32(rng) % 65536) / 2n;
    const vy =
      (BigInt(xorshift32(rng) % 65536) - 32768n) * 4n + BigInt(xorshift32(rng) % 65536) / 2n;
    particles.push({ px, py, vx, vy });
  }

  // Advance exactly TICKS fixed ticks with reflective wall bounces.
  for (let t = 0; t < TICKS; t++) {
    for (const p of particles) {
      p.px += p.vx;
      p.py += p.vy;
      if (p.px < 0n) {
        p.px = -p.px;
        p.vx = -p.vx;
      } else if (p.px >= MAX_POS) {
        p.px = 2n * MAX_POS - p.px;
        p.vx = -p.vx;
      }
      if (p.py < 0n) {
        p.py = -p.py;
        p.vy = -p.vy;
      } else if (p.py >= MAX_POS) {
        p.py = 2n * MAX_POS - p.py;
        p.vy = -p.vy;
      }
    }
  }

  // Hash all particle states.
  const bytes: number[] = [];
  for (const p of particles) {
    bytes.push(...toBytes(p.px), ...toBytes(p.py), ...toBytes(p.vx), ...toBytes(p.vy));
  }
  return fnv1a(bytes);
}

// ---- CLI entry point -------------------------------------------------------
if (
  typeof process !== "undefined" &&
  process.argv[1]?.replace(/\.js$/, "").endsWith("sim")
) {
  const args = process.argv.slice(2);
  const flagIdx = args.indexOf("--seed");
  const seed = Number(args[flagIdx + 1]);
  if (!Number.isInteger(seed)) {
    console.error("usage: node dist/sim.js --seed <integer>");
    process.exit(1);
  }
  console.log(runSim(seed));
}

