import { defineConfig } from "vitest/config";
import { execSync } from "node:child_process";

/**
 * Compile src/ -> dist/ before tests run so the child-process test can
 * spawn a freshly built CLI.
 */
function tscSetup() {
  return {
    name: "tsc-build",
    buildStart() {
      execSync("npx tsc", { stdio: "inherit", cwd: __dirname });
    },
  };
}

export default defineConfig({
  plugins: [tscSetup()],
  test: {
    environment: "node",
  },
});

