import { describe, it, expect } from "vitest";
import { execFileSync } from "node:child_process";
import { join } from "node:path";
import { runSim } from "./sim.js";

const CLI = join(__dirname, "..", "dist", "sim.js");

function runCli(seed: number): string {
  return execFileSync(process.execPath, [CLI, "--seed", String(seed)], {
    encoding: "utf8",
  }).trim();
}

describe("deterministic soak test", () => {
  it("produces the same hash for the same seed (in-process, twice)", () => {
    const a = runSim(42);
    const b = runSim(42);
    expect(a).toMatch(/^[0-9a-f]{8}$/);
    expect(a).toBe(b);
  });

  it("produces a different hash for a different seed", () => {
    expect(runSim(42)).not.toBe(runSim(43));
  });

  it("is stable across two separate process runs via the CLI", () => {
    const out1 = runCli(42);
    const out2 = runCli(42);
    expect(out1).toMatch(/^[0-9a-f]{8}$/);
    expect(out1).toBe(out2);
    // and matches the in-process result
    expect(out1).toBe(runSim(42));
  });
});

